class Buku {
    String judul;
    int tahun;

    Buku(String judul) {
        this(judul, 2024);
    }

    Buku(String judul, int tahun) {
        this.judul = judul;
        this.tahun = tahun;
    }

    void info() {
        System.out.println(judul + " (" + tahun + ")");
    }
}

